from collections import Counter
import math

class Solution:
    def minimumRounds(self, tasks: list[int]) -> int:
        count = Counter(tasks)
        rounds = 0
        for freq in count.values():
            if freq == 1:
                return -1
            rounds += math.ceil(freq / 3)
        return rounds

